// Extract variant data - handles ALL endpoint types
const baseJson = $('When Executed by Another Workflow').first().json;
const req = baseJson.request_json;

// Determine endpoint type
const endpoint = baseJson.endpoint;
const isStyleEndpoint = endpoint.includes('style');
const isVid1Single = endpoint === '/create-video-vid-1';
const isMultiClip = endpoint.includes('vid-1.2') || endpoint.includes('vid-1.3') || endpoint.includes('vid-1.4') || endpoint.includes('vid-1.5');

// Get the main description as fallback - this contains the actual video content description
const mainDescription = baseJson.description || 'Motivational video content';

// Build media descriptions based on endpoint type
let mediaDescriptions = [];
let mediaType = 'unknown';

if (isStyleEndpoint) {
  mediaType = 'image';
  mediaDescriptions = [req.imageDescription || mainDescription];
} else if (isVid1Single) {
  mediaType = 'video';
  mediaDescriptions = [req.videoDescription || mainDescription];
} else if (isMultiClip && req.clips?.length > 0) {
  mediaType = 'clips';
  mediaDescriptions = req.clips.map(clip => clip.description || mainDescription);
}

return [{
  json: {
    endpointType: {
      endpoint: endpoint,
      isStyleEndpoint: isStyleEndpoint,
      isVid1Single: isVid1Single,
      isMultiClip: isMultiClip,
      mediaType: mediaType
    },
    baseStructure: {
      endpoint: endpoint,
      audioUrl: req.audioUrl,
      instagramUrl: req.instagramUrl,
      original: req.original,
      quote: req.quote,
      author: req.author,
      duration: req.duration,
      overlay: req.overlay,
      description: baseJson.description,
      niche: baseJson.niche,
      transcription: baseJson.transcription,
      caption: baseJson.caption,
      imageUrl: req.imageUrl,
      imageDescription: req.imageDescription,
      videoUrl: req.videoUrl,
      videoDescription: req.videoDescription,
      clips: req.clips?.map(clip => ({
        start: clip.start,
        duration: clip.duration,
        volume: clip.volume,
        begin: clip.begin
      })) || [],
      captions: req.captions?.map(caption => ({
        text: caption.text,
        start: caption.start,
        duration: caption.duration
      })) || []
    },
    variableData: {
      mediaDescriptions: mediaDescriptions,
      mediaType: mediaType,
      captionTexts: req.captions?.map(caption => caption.text) || [],
      mainCaption: baseJson.caption,
      transcriptionRequired: baseJson.transcription,
      audioUrl: req.audioUrl
    },
    usernames: $input.first().json.usernames
  }
}];

// Parse AI output and reconstruct full variants
const raw = $json.output;
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();

let assetVariants;
try {
  assetVariants = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Failed to parse AI output: ' + error.message + ' | Raw: ' + cleaned);
}

const extractData = $('Extract Variant Data').first().json;
const { baseStructure, variableData, endpointType } = extractData;

const variants = assetVariants.map(assets => {
  const variant = {
    endpoint: baseStructure.endpoint,
    request_json: {
      audioUrl: baseStructure.audioUrl,
      original: baseStructure.original,
      watermark: assets.username
    },
    caption: assets.captionVariant || baseStructure.caption,
    description: baseStructure.description,
    niche: baseStructure.niche,
    transcription: baseStructure.transcription
  };

  if (baseStructure.quote) variant.request_json.quote = baseStructure.quote;
  if (baseStructure.author) variant.request_json.author = baseStructure.author;
  if (baseStructure.instagramUrl) variant.request_json.instagramUrl = baseStructure.instagramUrl;
  if (baseStructure.duration) variant.request_json.duration = baseStructure.duration;
  if (baseStructure.overlay !== undefined) variant.request_json.overlay = baseStructure.overlay;

  if (endpointType.isStyleEndpoint) {
    variant.request_json.imageUrl = assets.mediaAssets?.[0]?.url || baseStructure.imageUrl;
    variant.request_json.imageDescription = assets.mediaAssets?.[0]?.description || baseStructure.imageDescription;
  } else if (endpointType.isVid1Single) {
    variant.request_json.videoUrl = assets.mediaAssets?.[0]?.url || baseStructure.videoUrl;
    variant.request_json.videoDescription = assets.mediaAssets?.[0]?.description || baseStructure.videoDescription;
  } else if (endpointType.isMultiClip) {
    variant.request_json.clips = baseStructure.clips.map((clipTiming, i) => {
      const newAsset = assets.mediaAssets?.[i];
      return {
        ...clipTiming,
        videoUrl: newAsset?.url || variableData.mediaDescriptions[i],
        description: newAsset?.description || variableData.mediaDescriptions[i]
      };
    });
  }

  if (baseStructure.captions?.length > 0) {
    variant.request_json.captions = baseStructure.captions.map((captionTiming, i) => ({
      ...captionTiming,
      alt: assets.captionAlts?.[i]?.alt
    }));
  }

  if (assets.timingAdjustments && variant.request_json.clips) {
    assets.timingAdjustments.forEach((adj, i) => {
      if (variant.request_json.clips[i]) {
        if (adj.start !== undefined) variant.request_json.clips[i].start = adj.start;
        if (adj.duration !== undefined) variant.request_json.clips[i].duration = adj.duration;
      }
    });
  }

  return variant;
});

return variants.map(item => ({ json: item }));

